def max_product(num_str: str, N: int, K: int) -> int:
    if N == 0 or K == 0:
        return 0

    # Count the frequency of each digit in the number string
    from collections import Counter
    digit_counts = Counter(num_str)

    # Sort the digits based on their frequency
    sorted_digits = sorted(digit_counts.items(), key=lambda x: x[1], reverse=True)

    # Insert K multiplication signs maximally
    max_product = 1
    for digit in sorted_digits[:K]:
        max_product *= digit[0]

    # Reconstruct the maximum product number
    max_product_str = ''
    unused_digits = sorted_digits[K:]
    for i in range(N):
        if i < K:
            max_product_str += digit[0]
        else:
            max_product_str += unused_digits[i-K][0]

    return int(max_product_str)

def max_product(num_str: str, N: int, K: int) -> int:
    n = len(num_str)
    dp = [[0 for _ in range(K + 1)] for _ in range(n + 1)]
    prefix_sum = [0] * (n + 1)

    # Base case: If there are no multiplication signs, just take the product of all numbers
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] * int(num_str[i - 1])
        dp[i][0] = prefix_sum[i]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, K + 1):
            if i + j - 1 > N:
                continue
            if j == 1:
                dp[i + j][j] = prefix_sum[i] * prefix_sum[i + j]
            else:
                for x in range(i + 1, i + j + 1):
                    dp[i + j][j] = max(dp[i + j][j], dp[x][j - 1] * prefix_sum[i] * prefix_sum[x + 1])

    return dp[n][K]

def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string to a list of integers
    nums = [int(digit) for digit in num_str]

    # Function to calculate the product of a slice of the list
    def product Slice(arr, low, high):
        if low == high:
            return arr[low]
        mid = (low + high) // 2
        left_product = product_slice(arr, low, mid)
        right_product = product_slice(arr, mid + 1, high)
        left_max = arr[mid] * max(left_product, right_product)
        right_max = arr[mid + 1] * max(left_product, right_product)
        crossing_max = left_max + right_max
        return max(left_max, right_max, crossing_max)

    # Use the divide and conquer approach to find the maximum product
    return product_slice(nums, 0, N - 1)

