        return n

    dp = [[0, 0] for _ in range(n)]
    dp[0][0] = 1  # Base case: the ball starts with the first student

    for temp in range(1, m + 1):
        dp[0][1] += dp[temp - 1][0]
        dp[1][0] += dp[temp - 1][1]

