def count_passing_ways(n: int, m: int) -> int:
    def dp(i, remain):
        if remain == 0:
            return 1 if i == 0 else 0
        if i == 0:  # Ball has to return to the starting student
            return dp(i, remain - 1)
        return dp(i - 1, remain) + dp(i + 1, remain - 1)

    return dp(0, m) // 2  # // to handle cases where n is even

