def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ""

    root_value = postorder[-1]
    root_index = inorder.index(root_value)

    postorder_left = postorder[:root_index]
    postorder_right = postorder[root_index:-1]
    inorder_left = inorder[:root_index]
    inorder_right = inorder[root_index+1:]

    return root_value + preorder_traversal(inorder_left, postorder_left) + preorder_traversal(inorder_right, postorder_right)

def preorder_traversal(inorder: str, postorder: str) -> str:
    mapping = {char: i for i, char in enumerate(inorder)}
    root = postorder[-1]

    if len(inorder) == 1:
        return inorder

    left_inorder = inorder[:mapping[root]]
    right_inorder = inorder[mapping[root] + 1:]

    left_postorder = postorder[:len(left_inorder)]
    right_postorder = postorder[len(left_inorder) + 1:]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

