def hanoi_double_iterative(n: int) -> int:
    # Implementation of the iterative algorithm for the double-disc Hanoi Towers problem
    # which follows the known recursive relation
    # The total number of moves for n pairs of discs is 2n * 3^(n-1)
    return 2 * n * (3 ** (n - 1))

def hanoi_double_iterative(n: int) -> int:
    # Iterative approach to solve the double-disc Hanoi Tower problem
    if n % 2 == 0:
        initial_moves = 2 * (3 ** n - 3) + 2
    else:
        initial_moves = 2 * (3 ** (n // 2) - 3) + (n // 2) * (2 * (3 ** ((n // 2) - 1)) - 2)

    # Update the number of moves based on the height of the last move
    for i in range(n - 1):
        if i % 2 == 0:
            initial_moves += 2 * (3 ** (n // 2) - 3) + (i // 2) * (2 * (3 ** ((n // 2) - 1)) - 2)
        else:
            initial_moves += 2 * (3 ** (n // 2) - 3) + (i // 2) * (3 ** ((n // 2) - 1)) - 2

    return initial_moves

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    # Initialize the number of moves for n=1, n=2, and n=3
    moves = [2, 6, 14]

    # Compute the number of moves for n greater than 3 using recursion
    for i in range(4, n + 1):
        moves.append(4 * moves[i - 3] + 2)

    return moves[n]

def hanoi_double_iterative(n: int) -> int:
    moves = 0
    for i in range(n):
        moves += 2 * (2 ** i)
    return moves

def total_smoked_cigarettes(n, k):
    total_smoked = n  # Start with the initial number of cigarettes
    while n >= k:
        total_smoked += 1  # Exchange one butt for one new cigarette
        n -= k  # Update the number of cigarettes after the exchange
    return total_smoked
